// Shared memory optimized kernel for generic K, S, P
// Block size: 32x8 = 256 threads
// Output tile: 32x8
template <int BLOCK_W, int BLOCK_H>
__global__ void depthwise_conv2d_shm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int K, int S, int P) {

    // Determine the shared memory size dynamically or use max size
    // For K=3, S=1, we need (32+2)x(8+2) = 34x10 = 340 floats.
    // For K=7, S=2, we need (32*2+6)x(8*2+6) = 70x22 approx 1500 floats.
    // Let's allocate a sufficiently large static shared memory buffer or use dynamic shared memory.
    // Since we can't easily template K/S here without dispatch, we'll use dynamic shared memory or a fixed large buffer.
    // Max kernel size is usually small. Let's assume max K=7, max S=2.
    // However, to be safe and simple, let's start with the global memory version 
    // because correctly implementing halo loading for generic K/S/P is complex and error-prone.
    // We will rely on L1 cache which is very efficient on MI300X.

    // If we want to be slightly smarter, we can put weights in shared memory?
    // Weights are K*K. For K=3, 9 floats. Registers are fine.
}

__global__ void depthwise_conv2d_basic_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int K, int S, int P) {

    int w_out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int nc_idx = blockIdx.z;

    if (nc_idx >= N * C) return;

    int n = nc_idx / C;
    int c = nc_idx % C;

    // Offsets
    // input: N, C, H, W
    // weight: C, 1, K, K
    // output: N, C, H_out, W_out

    // Base pointers
    const float* input_ptr = input + (n * C + c) * ((long long)H * W);
    const float* weight_ptr = weight + c * (K * K);
    float* output_ptr = output + (n * C + c) * ((long long)H_out * W_out);

    float bias_val = (bias != nullptr) ? bias[c] : 0.0f;

    if (h_out_idx < H_out && w_out_idx < W_out) {
        float sum = 0.0f;

        int h_in_base = h_out_idx * S - P;
        int w_in_base = w_out_idx * S - P;

        for (int i = 0; i < K; ++i) {
            int h_in = h_in_base + i;
            if (h_in >= 0 && h_in < H) {
                for (int j = 0; j < K; ++j) {
                    int w_in = w_in_base + j;
                    if (w_in >= 0 && w_in < W) {
                        sum += input_ptr[h_in * W + w_in] * weight_ptr[i * K + j];
                    }
                }
            }
        }

        output_ptr[h_out_idx * W_out + w_out_idx] = sum + bias_val;
    }
}

torch::Tensor depthwise_conv2d_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding) {
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int K = weight.size(2);

    int H_out = (H + 2 * padding - K) / stride + 1;
    int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.defined()) {
        bias_ptr = bias.data_ptr<float>();
